from pathlib import Path
import nbformat
from nbclient import NotebookClient
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'notebooks'; OUT.mkdir(exist_ok=True)

def md(s):return nbformat.v4.new_markdown_cell(s)
def code(s):return nbformat.v4.new_code_cell(s)
def setup():return code('''from pathlib import Path\nimport sys\nROOT=Path.cwd()\nif not (ROOT/"src").exists(): ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/"src"))\nDATA=ROOT/"data"/"Student folder"\nprint("Project:",ROOT,"| data folder available:",DATA.exists())''')

def make(name,cells):
 nb=nbformat.v4.new_notebook(metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'}})
 nb.cells=cells; path=OUT/name; nbformat.write(nb,path); return path

p1=make('01_Dataset_Exploration.ipynb',[
md('''# 01 · Dataset Exploration\n\n**Round 1 walkthrough:** inspect the trip folders, count observations and road-network files, check time/coordinate quality, and create a first Folium map. The provided archive has training and student-test trips; evaluator-only data is not included.'''),setup(),
code('''import pandas as pd\nfrom pathsnap.eda import run\nrows=run(DATA,ROOT/"results"/"dataset_inventory.csv")\ninventory=pd.DataFrame(rows)\nsummary=inventory.groupby("partition").agg(trips=("trip_id","count"),gps_observations=("gps_rows","sum"),nodes=("node_rows","sum"),road_arcs=("arc_rows","sum"),reference_route_entries=("route_rows","sum"),invalid_rows_removed=("preprocessing_rows_removed","sum"),nonincreasing_timestamps=("nonincreasing_timestamp_steps","sum"),gaps_over_5s=("time_gap_over_5s_steps","sum"))\ndisplay(summary)'''),
md('''## File formats and how they relate\n\n- `.track`: longitude, latitude, timestamp in seconds.\n- `.nodes`: node longitude and latitude; each row index is a node ID.\n- `.arcs`: directed from-node and to-node IDs; each row index is an arc ID.\n- `.route`: chronological reference arc IDs for the trip.\n\nThe GPS rows do not correspond one-to-one to node or arc rows. Each trip has its own road graph.'''),
code('''from pathsnap.data import read_trip\nfrom pathsnap.matcher import generate_candidates\nfrom pathsnap.visualize import create_map\nfrom IPython.display import IFrame,display\ntrip=read_trip(DATA/"student_test"/"00000000","student_test")\nbatch=generate_candidates(trip,k=12)\nnearest=batch.ids[range(len(batch.ids)),batch.features[:,:,0].argmin(axis=1)]\nmap_path=ROOT/"maps"/"phase1_eda_map.html"\ncreate_map(trip,batch,nearest,map_path)\nprint("Trip:",trip.trip_id,"GPS rows:",len(trip.track),"nodes:",len(trip.nodes),"arcs:",len(trip.arcs),"reference arcs:",len(trip.route))\nprint("Candidate miss rate:",round(100*float(batch.candidate_miss.mean()),2),"%")\ndisplay(IFrame(src=str(map_path),width="100%",height=480))'''),
md('''The first map separates observed GPS, candidate road context, reference route, and nearest-road baseline into layers. It is a visual exploration of an actual student-test development trip.''')])

p2=make('02_Data_Preprocessing.ipynb',[
md('''# 02 · Data Preprocessing\n\n**Round 1 walkthrough:** show how GPS records are validated, how timestamp order and gaps are handled, and how the road graph is checked. Cleaning preserves trajectory order and never edits the supplied files.'''),setup(),
code('''import numpy as np\nimport pandas as pd\nfrom pathsnap.data import read_trip\ntrip=read_trip(DATA/"train"/"00000001","train")\nprint({"input_GPS_rows":trip.raw_track_rows,"rows_after_cleaning":len(trip.track),"rows_removed":trip.raw_track_rows-len(trip.track),"nonincreasing_steps":int(np.sum(np.diff(trip.track[:,2])<=0)),"timestamp_gap_over_5s":int(np.sum(np.diff(trip.track[:,2])>5)),"coordinate_min_lon":float(trip.track[:,0].min()),"coordinate_max_lon":float(trip.track[:,0].max()),"coordinate_min_lat":float(trip.track[:,1].min()),"coordinate_max_lat":float(trip.track[:,1].max())})\ndisplay(pd.DataFrame(trip.track[:8],columns=["longitude","latitude","timestamp_s"]))'''),
md('''## Cleaning and transformation choices\n\n1. Require finite coordinates and timestamps and legal longitude/latitude ranges.\n2. Drop duplicate or backward timestamps while preserving the observed order; do not sort GPS points into a different path.\n3. Keep long gaps and divide displacement by actual elapsed time when computing speed.\n4. Convert coordinates to a local metre-scale frame before computing physical distances.\n5. Exclude arcs with invalid node references or zero geometric length from candidate geometry.\n\nThe supplied archive currently has zero invalid coordinates and zero non-increasing timestamps, so the cleaning rules remove no rows in this run.'''),
code('''from scipy.sparse import coo_matrix\nfrom scipy.sparse.csgraph import connected_components\narcs=trip.arcs; n=len(trip.nodes)\nvalid=(arcs[:,0]>=0)&(arcs[:,1]>=0)&(arcs[:,0]<n)&(arcs[:,1]<n)\nvalid_arcs=arcs[valid].astype(int)\ndegree=np.bincount(valid_arcs.ravel(),minlength=n) if len(valid_arcs) else np.zeros(n,dtype=int)\ngraph=coo_matrix((np.ones(len(valid_arcs)),(valid_arcs[:,0],valid_arcs[:,1])),shape=(n,n)).tocsr()\ncomponents,labels=connected_components(graph,directed=False,return_labels=True)\ncomponent_sizes=np.bincount(labels)\nprint({"nodes":n,"arcs":len(arcs),"invalid_arc_rows":int((~valid).sum()),"isolated_nodes":int((degree==0).sum()),"weak_components":int(components),"largest_component_nodes":int(component_sizes.max()),"largest_component_fraction":round(float(component_sizes.max()/n),4)})'''),
md('''A weakly connected component treats a directed road arc as an undirected connection for this first connectivity check. The predictor still retains directed arc orientation in its features and transition rule.''')])

p3=make('03_Candidate_Generation_Features.ipynb',[
md('''# 03 · Candidate Generation and Features\n\n**Round 1 walkthrough:** turn each noisy GPS point into a small set of possible road segments, measure the candidate miss rate, and inspect the feature vector used by all five classifiers.'''),setup(),
code('''import pandas as pd, numpy as np\nfrom pathsnap.data import read_trip\nfrom pathsnap.matcher import generate_candidates,FEATURE_NAMES\ntrip=read_trip(DATA/"train"/"00000001","train")\nbatch=generate_candidates(trip,k=12)\nprint("GPS observations:",len(trip.track),"candidate count per observation:",batch.ids.shape[1])\nprint("Candidate miss rate:",round(float(batch.candidate_miss.mean())*100,2),"%")\nobs=10\nview=pd.DataFrame(batch.features[obs],columns=FEATURE_NAMES)\nview.insert(0,"candidate_arc_id",batch.ids[obs])\nview["reference_candidate"]=batch.ids[obs]==batch.truth[obs]\nprint("Reference-route arc for sample observation:",int(batch.truth[obs]))\ndisplay(view.sort_values("distance_m").reset_index(drop=True))'''),
md('''## Why these five features?\n\n- **Distance to segment (metres):** the nearest physical distance is a direct cue for the road that produced a noisy GPS point.\n- **Heading difference (radians):** helps separate parallel or opposite-direction road candidates using recent movement.\n- **Along-segment fraction:** shows where the point projects between the candidate segment’s endpoints.\n- **Segment length (metres):** provides local geometry context.\n- **GPS speed (metres/second):** adds movement context and respects timestamp gaps.\n\nThis is a compact, task-motivated first set. A formal feature-ablation experiment remains future work.'''),
code('''import matplotlib.pyplot as plt\nfig,ax=plt.subplots(figsize=(7,4))\nax.hist(batch.features[:,:,0].ravel(),bins=40,color="#3b82c4")\nax.set(xlabel="GPS-to-candidate distance (m)",ylabel="Candidate count",title="Candidate distance distribution")\nfig.tight_layout()''')])

p4=make('04_ML_Model_Training.ipynb',[
md('''# 04 · ML Model Training\n\n**Round 1 walkthrough:** train and compare five distinct algorithms. A whole-trip holdout is used so observations from a trip do not appear in both fitting and validation. The student-test partition is kept for the permitted development comparison.'''),setup(),
md('''The target is binary: a candidate is positive when it matches the closest arc in that trip’s supplied reference route. Arc IDs are trip-local, so the model learns general geometry and movement patterns rather than one global road-ID vocabulary. Candidate-miss observations are counted and omitted from ranker fitting because the correct arc is not available to choose.'''),
code('''from pathsnap.matcher import train_compare\nrows,selected_model,fitted_model=train_compare(DATA,ROOT/"outputs",k=12,seed=42,max_candidates=200_000)\nprint("Validation-selected model:",selected_model)\nprint("Saved final fit:",ROOT/"outputs"/"phase1_model.joblib")'''),
code('''import pandas as pd\ncomparison=pd.read_csv(ROOT/"outputs"/"model_comparison.csv")\ncolumns=["model","training_seconds","validation_top1_accuracy","validation_candidate_macro_f1","student_test_top1_accuracy","student_test_candidate_macro_f1","student_test_candidate_log_loss","student_test_inference_seconds"]\ndisplay(comparison[columns].style.format({c:"{:.4f}" for c in columns if c!="model"}))'''),
md('''## Configurations shown in this run\n\n- Logistic Regression: standardized features, max 250 iterations, balanced classes.\n- KNN: standardized features, 9 distance-weighted neighbors, 5,000 balanced candidate rows for practical inference.\n- Decision Tree: depth 14, minimum 4 rows per leaf, balanced classes.\n- Random Forest: 80 trees, depth 18, minimum 2 rows per leaf, balanced subsampling.\n- Hist Gradient Boosting: 100 iterations, learning rate 0.08, 15 maximum leaf nodes, L2 regularization 1.0.''')])

p5=make('05_Initial_Evaluation.ipynb',[
md('''# 05 · Initial Evaluation and Model Selection\n\n**Round 1 walkthrough:** compare measured metrics, select the provisional model based on the training-trip holdout, and show the first HMM/Viterbi tradeoff. Student-test results are development metrics only, not evaluator results.'''),setup(),
code('''import pandas as pd, json\nfrom IPython.display import IFrame,display\ncomparison=pd.read_csv(ROOT/"outputs"/"model_comparison.csv")\nroute_summary=json.loads((ROOT/"outputs"/"route_decoder_comparison.summary.json").read_text())\ndisplay(comparison)\nprint("Route decoder summary:",route_summary)'''),
code('''import matplotlib.pyplot as plt\nnames=comparison["model"].tolist();x=range(len(names));w=.38\nfig,ax=plt.subplots(figsize=(10,5))\nax.bar([i-w/2 for i in x],comparison["validation_top1_accuracy"],width=w,label="Training-trip validation")\nax.bar([i+w/2 for i in x],comparison["student_test_top1_accuracy"],width=w,label="Student test (development)")\nax.set_xticks(list(x),names,rotation=20,ha="right");ax.set_ylabel("Observation-level Top-1 accuracy");ax.set_ylim(0,1);ax.legend();ax.grid(axis="y",alpha=.25);fig.tight_layout()'''),
md('''## Why the initial model is Hist Gradient Boosting\n\nIt leads the held-out training trips at **71.45% Top-1**, narrowly above Random Forest at **71.09%**. Student-test Top-1 is **75.45%** versus **75.14%** for Random Forest, with a measured inference time of **0.108 s** versus **0.192 s**. The small validation margin means this is provisional; group-aware cross-validation and hyperparameter tuning are still required.'''),
md('''## HMM/Viterbi tradeoff\n\nAcross 10 student-test trips, classifier Top-1 is **75.45%**; the initial HMM/Viterbi decoder is **57.64%**. Strict direct-arc continuity rises from **25.41%** to **73.86%**. It makes the route more locally connected but overrules too many correct pointwise predictions. A better transition model should allow plausible multi-arc paths, incorporate travel time and distance, and be tuned only on allowed development data.'''),
code('''route_rows=pd.read_csv(ROOT/"outputs"/"route_decoder_comparison.csv")\ndisplay(route_rows)\nprint("Working Folium demo:",ROOT/"maps"/"phase1_demo.html")\ndisplay(IFrame(src=str(ROOT/"maps"/"phase1_demo.html"),width="100%",height=500))'''),
md('''## Measures and limits to say aloud\n\n- **Top-1:** best-scored road candidate equals the reference arc for that GPS observation.\n- **Candidate miss rate:** the reference arc was not among the 12 options, so no ranker could select it.\n- **Candidate Macro F1 / log loss:** binary candidate-row metrics (correct candidate vs alternatives), not a global arc-ID score.\n- **Direct-arc continuity:** fraction of adjacent predictions where one arc’s end node equals the next arc’s start node.\n\nNo evaluator-test folder was supplied. The report and maps use real student-test development outputs; do not present them as final evaluation scores.''')])

# Remove the earlier two-notebook draft so the Round 1 set is exactly the five focused files.
for old in OUT.glob('*.ipynb'):
    if old.name not in {p1.name,p2.name,p3.name,p4.name,p5.name}: old.unlink()
for path in [p1,p2,p3,p4,p5]:
    nb=nbformat.read(path,as_version=4)
    executed=NotebookClient(nb,timeout=1800,kernel_name='python3',resources={'metadata':{'path':str(ROOT)}}).execute()
    nbformat.write(executed,path)
    print('Executed and saved:',path.name)
